7.4 Floats, functions, conditionals
We will now learn how to deal with floats, how to define our own functions, and how to write conditionals (if/else).

     Toggle code


         Download code





// initialize 4 floats (decimals)
// time and 3 more variables to be plotted
float t = 0, x1 = 0, x2 = 0, x3 = 0;

void setup() {
  // initialize serial communication with computer:
  Serial.begin(9600);
}

/*
 * This is how you define a function.
 * In this case, the function returns a float (decimal)
 */
float my_sine(float time) {
  return sin(time);
}

float my_cosine(float time) {
  float double_time;              // you can define internal variables,
  double_time = 2.0 * time;       // write as many commands as you want
  return 2.0 * cos(double_time);  // in the end, return float
}

void loop() {
  x1 = my_sine(t);
  x2 = my_cosine(t);
  // now let's make a square wave
  if (x1 &gt; 0) {
    x3 = -1.0;
  } else {
    x3 = 1.0;
  }
  Serial.print("sin:"); Serial.print(x1); Serial.print("\t");
  Serial.print("cos:"); Serial.print(x2); Serial.print("\t");
  Serial.print("square:"); Serial.print(x3);
  Serial.println();
  delay(50);        // 1000 ms delay
  t += 0.05;
}

7.5 Serial read
We can also read data from the Serial Monitor and use it to control the behavior of the ESP32. In this example, the ESP32 waits for you to type a number into the Serial Monitor and then blinks that number of times.

     Toggle code


         Download code





// serial-read-blink.ino
String inputString = "";

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(115200);
  Serial.println("Type a number and press Enter:");
}

void loop() {
  // check if data is available in the Serial Monitor
  if (Serial.available()) {
    inputString = Serial.readStringUntil('\n');
    int n = inputString.toInt();  // convert text to integer

    Serial.print("Blinking ");
    Serial.print(n);
    Serial.println(" times");

    for (int i = 0; i &lt; n; i++) {
      digitalWrite(LED_BUILTIN, HIGH);
      delay(200);
      digitalWrite(LED_BUILTIN, LOW);
      delay(200);
    }

    Serial.println("Done. Type another number:");
  }
}

