  ThingSpeak.begin(client);
}

void loop() {
  // Set the values to be sent to ThingSpeak
  ThingSpeak.setField(1, 11);
  ThingSpeak.setField(2, 22);
  ThingSpeak.setField(3, 33);
  ThingSpeak.setField(4, 44);

